<template><div class="page-shell"><section class="page-heading"><div><p class="eyebrow">Diagnostics / 07</p><h2>System monitoring</h2><p>Real-time system performance and health monitoring.</p></div><span class="status-pill active">Live telemetry</span></section><div class="metric-grid monitoring-metrics"><div v-for="metric in systemMetrics" :key="metric.name" class="metric-tile"><span>{{ metric.name }}</span><strong>{{ metric.value }}<small>{{ metric.unit }}</small></strong><div class="health-bar"><span :style="{width:`${metric.percent}%`}"></span></div></div></div><div class="page-grid two"><article class="data-card graph-card"><div class="card-header"><h3>Performance graph</h3><span class="eyebrow">LAST 30 MIN</span></div><div class="graph-placeholder"><div v-for="n in 12" :key="n" :style="{height:`${25 + (n * 13) % 62}%`}"></div></div></article><article class="data-card"><div class="card-header"><h3>System logs</h3><span class="status-pill active">Streaming</span></div><div class="log-list"><div v-for="log in logs" :key="log.time" class="log-row"><span>{{ log.time }}</span><b :class="log.level.toLowerCase()">{{ log.level }}</b><p>{{ log.message }}</p></div></div></article></div></div></template>
<script setup lang="ts">import { onMounted,onUnmounted,ref } from 'vue'
const systemMetrics=ref([{name:'CPU usage',value:45,unit:'%',percent:45},{name:'Memory',value:62,unit:'%',percent:62},{name:'Temperature',value:42,unit:'°C',percent:42},{name:'Power draw',value:68,unit:'W',percent:68}]); const logs=[{time:'14:32:15',level:'INFO',message:'System initialization completed successfully'},{time:'14:31:42',level:'INFO',message:'ROS node connections established'},{time:'14:31:15',level:'WARN',message:'High CPU usage detected'},{time:'14:30:58',level:'INFO',message:'All sensors operational and calibrated'},{time:'14:30:12',level:'ERROR',message:'Camera 03 connection interrupted'}]; let timer:ReturnType<typeof setInterval>|undefined; onMounted(()=>{timer=setInterval(()=>systemMetrics.value.forEach(metric=>metric.value=Math.max(20,Math.min(90,metric.value+Math.floor(Math.random()*7)-3))),2000)}); onUnmounted(()=>{if(timer)clearInterval(timer)})</script>
<style scoped>.monitoring-metrics{margin-top:22px}.metric-tile strong small{font-size:12px;color:var(--ink-muted)}.metric-tile .health-bar{margin-top:17px}.graph-placeholder{display:flex;height:270px;align-items:flex-end;gap:10px;padding:18px;background:repeating-linear-gradient(to bottom,var(--surface-soft) 0,var(--surface-soft) 1px,transparent 1px,transparent 52px);border-bottom:1px solid var(--line)}.graph-placeholder div{flex:1;background:var(--ink);opacity:.8}.log-list{display:grid;gap:13px}.log-row{display:grid;grid-template-columns:60px 48px 1fr;gap:8px;align-items:start;padding-bottom:12px;border-bottom:1px solid var(--line);font:10px 'DM Mono',monospace}.log-row span{color:var(--ink-muted)}.log-row b{font-size:9px}.log-row p{margin:0;color:var(--ink-soft);font:11px Inter,sans-serif}.info{color:#6287a6}.warn{color:#bf9228}.error{color:#ba5148}</style>
